use crate::{ErasedSnapshotRetirement,NativeDecodeControl,NativeDecodeProgress,NativeDecodeRetirementRecipient,RetirementDemand,ValueError,ValueRefusalKind,retained_clone::{RetainedCloneGrant,RetainedCloneProgress},retirement::{controlled::ControlledRetirement,RetirementCursor}};
fn fixture()->serde_json::Value{serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap()}
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth.max(1)}}
fn observe<T>(operation:impl FnOnce()->T)->(T,(usize,usize)){crate::observe_retirement_allocations(operation)}

/// 🧾️ The actual original receipt and recipient survive cancelled work while retirement receives only its paid hop allowance.
#[test]
fn native_retirement_loan_preserves_original_cancelled_ledger_and_grant(){
 let law=fixture();let mut accepted=|_|true;let mut recipient=NativeDecodeRetirementRecipient::new();let mut control=NativeDecodeControl::new(128,&mut accepted);control.install_retirement_recipient(&mut recipient).unwrap();control.charge(law["originalBytes"].as_u64().unwrap()as usize).unwrap();let ledger=control.ledger_identity();let recipient_id=control.retirement_recipient_identity();let mut owner=control.pause_with_retirement().unwrap();let calls=std::cell::Cell::new(0usize);let mut cancelled=|_:NativeDecodeProgress|{calls.set(calls.get()+1);false};assert_eq!(owner.decode(&mut cancelled,|control|control.checkpoint()).unwrap_err().kind,ValueRefusalKind::Canceled);let capacity=law["charges"].as_array().unwrap().iter().map(|n|n.as_u64().unwrap()as usize).sum();let g=grant(RetirementDemand{capacity_bytes:capacity,depth:1,..Default::default()});let before=owner.owned_bytes();let mut visits=0;let denied=RetainedCloneGrant{maximum_items:0,..g};assert!(owner.retire(denied,&mut cancelled,|_|{visits+=1;Ok(())}).is_err());assert_eq!(visits,0);assert_eq!(owner.owned_bytes(),before);
 owner.retire(g,&mut cancelled,|loan|{assert_eq!(loan.ledger_identity(),ledger);assert_eq!(loan.retirement_recipient_identity(),recipient_id);{let close:&mut dyn crate::native_decoding::NativeDecodeCloseControl=loan;assert_eq!(close.ledger_identity(),ledger);assert_eq!(close.retirement_recipient_identity(),recipient_id);for n in law["charges"].as_array().unwrap(){close.charge(n.as_u64().unwrap()as usize)?;}}let before=calls.get();assert_eq!(loan.charge(1).unwrap_err().kind,ValueRefusalKind::OwnershipLimit);assert_eq!(calls.get(),before);assert_eq!(loan.owned_bytes(),law["expectedBytes"].as_u64().unwrap()as usize);Ok(())}).unwrap();assert_eq!(owner.owned_bytes(),35);assert_eq!(owner.decode(&mut cancelled,|control|control.checkpoint()).unwrap_err().kind,ValueRefusalKind::Canceled);let(detached,_)=owner.detach();assert_eq!(detached.owned_bytes(),35);assert!(crate::ErasedSnapshotRetirement::terminal_is_empty(&recipient));eprintln!("[DEBUG] original cancelled native ledger={ledger} recipient={recipient_id:?} cumulative35 exact retirement-only hop capacity3, semantic cancellation preserved");
}

/// 🧳️ Real returned payloads close through their exact original recipient after cancellation at every authored frontier.
#[test]
fn native_retirement_loan_closes_original_returned_payload_after_cancellation(){
 let law=fixture();for length in law["payloadBytes"].as_array().unwrap(){let length=length.as_u64().unwrap()as usize;for cut in law["cuts"].as_array().unwrap(){let cut=cut.as_u64().unwrap()as usize;let text="x".repeat(length);let mut accepted=|_|true;let mut recipient=NativeDecodeRetirementRecipient::new();let mut control=NativeDecodeControl::new(1<<30,&mut accepted);control.install_retirement_recipient(&mut recipient).unwrap();let identity=control.retirement_recipient_identity();let ledger=control.ledger_identity();let wrapper=std::mem::size_of::<ControlledRetirement<String>>();let(error,mut total)=observe(||control.with_retirement_owner::<(),ValueError>(wrapper,|control|{let owned=control.copy_text(&text).unwrap();let owner=Box::new(ControlledRetirement::new(owned).unwrap());(Err(ValueError::literal(ValueRefusalKind::InvalidValue,"original payload retained for funded closure")),Some(owner))}).unwrap_err());assert_eq!(error.kind,ValueRefusalKind::InvalidValue);let prepared=control.owned_bytes();assert_eq!(prepared,total.0);let mut owner=control.pause_with_retirement().unwrap();let mut cancelled=|_|false;let mut turns=0;while owner.retire(grant(RetirementDemand{depth:1,..Default::default()}),&mut cancelled,|loan|Ok(loan.has_retirement_owner())).unwrap(){let d=owner.retire(grant(RetirementDemand{depth:1,..Default::default()}),&mut cancelled,|loan|loan.retirement_demands(4096)).unwrap();assert!(d.copy_bytes<=4096);let g=grant(d);owner.retire(g,&mut cancelled,|loan|{assert_eq!(loan.ledger_identity(),ledger);assert_eq!(loan.retirement_recipient_identity(),identity);for axis in 0..5{let mut denied=g;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes=d.copy_bytes-1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes=d.capacity_bytes-1,3 if d.release_bytes>0=>denied.maximum_release_bytes=d.release_bytes-1,4 if d.depth>0=>denied.maximum_depth=d.depth-1,_=>continue}let(s,heap)=observe(||loan.close_retirement_recipient(denied).unwrap());assert_eq!(s.progress(),RetainedCloneProgress::default());assert_eq!(heap,(0,0));}let(s,heap)=observe(||loan.close_retirement_recipient(g).unwrap());assert!(s.progress().fits(g));assert_eq!(heap,(s.progress().retained_capacity_bytes,s.progress().released_bytes));total.0+=heap.0;total.1+=heap.1;Ok(())}).unwrap();turns+=1;if turns==cut{assert_eq!(owner.decode(&mut cancelled,|control|control.checkpoint()).unwrap_err().kind,ValueRefusalKind::Canceled);}assert!(turns<10000);}assert_eq!(owner.owned_bytes(),total.0);let(detached,_)=owner.detach();assert_eq!(detached.owned_bytes(),total.0);assert!(crate::ErasedSnapshotRetirement::terminal_is_empty(&recipient));assert_eq!(total.0,total.1);assert_eq!(observe(||drop(recipient)).1,(0,0));eprintln!("[DEBUG] original cancelled retirement length={length} cut={cut} turns={turns} born={} released={} originalLedger=true originalRecipient=true deniedAxes5 terminalDrop0",total.0,total.1);
 }}
}
